import java.io.*;import java.net.ServerSocket;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.stream.*;
/** Repeats official two TNT 46 place, flint-and-steel 259 prime of one, and Packet60 chain in two fresh worlds. */
public final class RemainingTntPlaceCycle{
 private static final String ID="m417-remaining-tnt-place";private final Path root=Paths.get("").toAbsolutePath().normalize(),smoke=root.resolve("smokes").resolve(ID),build=root.resolve(".worldline/smokes").resolve(ID);private final Properties config=new Properties(),artifact=new Properties();
 public static void main(String[]a){if(!Arrays.equals(a,new String[]{ID})){System.err.println("usage: java tools/smoke/RemainingTntPlaceCycle.java "+ID);System.exit(2);}try{new RemainingTntPlaceCycle().execute();}catch(Exception e){System.err.println("remaining tnt place failed: "+e.getMessage());System.exit(1);}}
 private void execute()throws Exception{load(smoke.resolve("smoke.properties"),config);load(root.resolve("artifacts/minecraft-b1.7.3-server.properties"),artifact);require(ID.equals(value(config,"id"))&&value(config,"server.jar.sha256").equals(value(artifact,"expected.sha256")),"descriptor drift");require(value(config,"username").equals("TntChain417")&&value(config,"username").length()<=16,"actor username drift");require(value(config,"expected.signal").contains("tnt1=")&&value(config,"expected.signal").contains("tnt2=")&&value(config,"expected.signal").contains("46:0->0:0")&&value(config,"expected.signal").contains("flint=259")&&value(config,"expected.signal").contains("packet60")&&value(config,"expected.signal").contains("strength4"),"set signal must name multiple TNT 46 cells and Packet60");require(!value(config,"expected.signal").contains("strength5")&&!value(config,"expected.signal").contains("packet17"),"TNT chain must not claim nether-bed Packet60 strength 5");Path official=root.resolve(value(artifact,"local.path")).normalize();verifyArtifact(official);recreate(build);Path classes=compile();Outcome first=run(classes,official,build.resolve("first")),second=run(classes,official,build.resolve("second"));require(first.signal.equals(second.signal)&&first.trace.equals(second.trace)&&first.signature.equals(second.signature),"fresh remaining-tnt-place results diverged\n"+first.signal+"\n"+second.signal);require(first.signal.contains("tnt1=")&&first.signal.contains("tnt2=")&&first.signal.contains("46:0->0:0")&&first.signal.contains("flint=259")&&first.signal.contains("packet60=strength4")&&first.signal.contains("chain=true")&&first.trace.contains("packet60-strength4")&&!first.signal.contains("strength5")&&!first.trace.contains("tnt-prime-set")&&!first.trace.contains("nether"),"live set signal missing two TNT 46 cells, flint 259, Packet60 chain, or collapsed to M381/M359");String expected=value(config,"expected.signature");if(expected.equals("pending")||Boolean.getBoolean("worldline.m417.diagnostic")){System.out.println("FROZEN");System.out.println("  "+first.signal);System.out.println("  trace: "+first.trace);System.out.println("  signature: "+first.signature);return;}require(first.signal.equals(value(config,"expected.signal"))&&first.signature.equals(expected),"M417 frozen evidence drift");Files.writeString(build.resolve("evidence.txt"),"id="+ID+"\nservers=2\nclients=4\nfirst="+first.signal+"\nsecond="+second.signal+"\ntrace="+first.trace+"\nsignature="+first.signature+"\n",StandardCharsets.UTF_8);System.out.println("FROZEN");System.out.println("  "+first.signal);System.out.println("  signature: "+first.signature);}
 private Outcome run(Path classes,Path official,Path workspace)throws Exception{Exception last=null;for(int attempt=0;attempt<2;attempt++){try{if(Files.exists(workspace))recreate(workspace);String output=capture(root,Arrays.asList("java","-classpath",classes+separator()+product("api"),"worldline.smoke.remainingtntplaceb173.RemainingTntPlaceSmoke",official.toString(),workspace.toString(),Integer.toString(freePort()),value(config,"seed"),value(config,"username"),value(config,"chunk.x"),value(config,"chunk.z"),value(config,"fixture.ticks"),value(config,"fuse.ticks")));return new Outcome(line(output,"WORLDLINE_M417_TRACE="),line(output,"WORLDLINE_M417_SIGNATURE="),line(output,"WORLDLINE_M417_SET="));}catch(Exception e){last=e;if(attempt==0&&eof(e)){System.out.println("M417 retrying one EOF");Thread.sleep(5000L);continue;}throw e;}}throw last;}
 private Path compile()throws Exception{Path output=build.resolve("adapter-classes");Files.createDirectories(output);List<String>command=new ArrayList<>(Arrays.asList("javac","-encoding","UTF-8","--release","8","-Xlint:all,-options","-Werror","-classpath",product("api").toString(),"-d",output.toString()));command.addAll(javaFiles(root.resolve("adapters/b173-server/src/main/java")));command.addAll(javaFiles(smoke.resolve("src")));capture(root,command);return output;}
 private void verifyArtifact(Path p)throws Exception{require(Files.isRegularFile(p),"server artifact absent");require(Files.size(p)==Long.parseLong(value(artifact,"expected.bytes"))&&digest(p,"SHA-1").equals(value(artifact,"expected.sha1"))&&digest(p,"SHA-256").equals(value(artifact,"expected.sha256")),"server artifact drift");}private List<String>javaFiles(Path s)throws IOException{try(Stream<Path>p=Files.walk(s)){return p.filter(x->x.toString().endsWith(".java")).sorted().map(Path::toString).collect(Collectors.toList());}}private String capture(Path d,List<String>c)throws Exception{Process p=new ProcessBuilder(c).directory(d.toFile()).redirectErrorStream(true).start();String o=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(p.waitFor()!=0)throw new IllegalStateException(c.get(0)+" failed\n"+o);return o;}private void recreate(Path t)throws IOException{if(Files.exists(t)){require(t.startsWith(root.resolve(".worldline"))&&!t.equals(root),"unsafe build path");try(Stream<Path>p=Files.walk(t)){for(Path f:p.sorted(Comparator.reverseOrder()).collect(Collectors.toList()))Files.delete(f);}}Files.createDirectories(t);}private void load(Path p,Properties t)throws IOException{try(Reader r=Files.newBufferedReader(p,StandardCharsets.UTF_8)){t.load(r);}}private String value(Properties p,String k){String v=p.getProperty(k);require(v!=null&&!v.trim().isEmpty(),"missing "+k);return v.trim();}private String digest(Path p,String a)throws Exception{MessageDigest d=MessageDigest.getInstance(a);try(InputStream in=Files.newInputStream(p)){byte[]b=new byte[8192];int n;while((n=in.read(b))>=0)d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}private int freePort()throws IOException{try(ServerSocket s=new ServerSocket(0)){return s.getLocalPort();}}private Path product(String n){return root.resolve(".worldline/build/classes").resolve(n);}private String separator(){return System.getProperty("path.separator");}private String line(String o,String p){return o.lines().filter(x->x.startsWith(p)).findFirst().orElseThrow(()->new IllegalStateException("missing "+p+"\n"+o)).substring(p.length());}private static boolean eof(Exception e){for(Throwable t=e;t!=null;t=t.getCause()){if(t instanceof EOFException)return true;String m=t.getMessage();if(m!=null&&m.toUpperCase(Locale.ROOT).contains("EOF"))return true;}return false;}private static void require(boolean v,String m){if(!v)throw new IllegalStateException(m);}private static final class Outcome{final String trace,signature,signal;Outcome(String t,String s,String l){trace=t;signature=s;signal=l;}}
}
